import { BedrockEmbeddings } from "@langchain/aws";

const embeddings = new BedrockEmbeddings({
  region: "us-east-1",
  credentials: {
    accessKeyId: process.env.AWS_ACCESS_KEY_ID!,
    secretAccessKey: process.env.AWS_SECRET_ACCESS_KEY!,
  },
  model: "amazon.titan-embed-text-v2:0",
  dimensions: 512,
  modelParameters: { normalize: true },
});

const vector = await embeddings.embedQuery("A colorful sock company");
console.log(vector);

import { ChatAnthropic } from "@langchain/anthropic";

const model = new ChatAnthropic({
  model: "claude-sonnet-4-5-20250929",
  temperature: 0,
});

const response = await model.invoke("Translate 'Hello' into French.");
console.log(response.content);

import { ChatOllama } from "@langchain/ollama";

const llm = new ChatOllama({
  model: "llama-3.1:8b",
  temperature: 0,
});

const result = await llm.invoke('Translate "I love programming" into French.');
console.log(result.content);

import { ChatVertexAI } from "@langchain/google-vertexai";

const model = new ChatVertexAI({
  model: "gemini-3.8-flash",
  temperature: 0,
  maxRetries: 2,
});

const response = await model.invoke("Explain closures in JavaScript.");
console.log(response.content);

import { Chroma } from "@langchain/community/vectorstores/chroma";
import { OpenAIEmbeddings } from "@langchain/openai";

const store = new Chroma(new OpenAIEmbeddings({
  model: "text-embedding-3-small",
}), { collectionName: "notes", host: "localhost" });

await store.addDocuments([
  { pageContent: "Chroma stores vectors.", metadata: { topic: "db" } },
]);

const docs = await store.similaritySearch("Where are vectors stored?", 1);
console.log(docs[0].pageContent);

import { CohereRerank } from "@langchain/cohere";
import { Document } from "@langchain/core/documents";

const reranker = new CohereRerank({
  apiKey: process.env.COHERE_API_KEY,
  topN: 2,
});

const documents = [
  new Document({ pageContent: "Paris is the capital of France." }),
  new Document({ pageContent: "Berlin is the capital of Germany." }),
];

const results = await reranker.compressDocuments(
  documents,
  "What is the capital of France?"
);

console.log(results);

import { FaissStore } from "@langchain/community/vectorstores/faiss";
import { MemoryVectorStore } from "langchain/vectorstores/memory";

const store = await FaissStore.fromTexts(
  ["LangChain stores vectors for similarity search."],
  [{ topic: "vectors" }],
  embeddings,
);

const results = await store.similaritySearch("How are vectors searched?", 1);
console.log(results[0].pageContent);

